import{_ as n,C as i,c as l,o as c,a3 as o,G as r,j as e,a as s}from"./chunks/framework.Dokpd4od.js";const P=JSON.parse('{"title":"Portal and sign-in","description":"","frontmatter":{},"headers":[],"relativePath":"master/website/customers/portal-and-sign-in.md","filePath":"master/website/customers/portal-and-sign-in.md","lastUpdated":1792041590000}'),d={name:"master/website/customers/portal-and-sign-in.md"};function g(h,t,p,m,u,w){const a=i("ImagePopup");return c(),l("div",null,[t[0]||(t[0]=o('<h1 id="portal-and-sign-in" tabindex="-1">Portal and sign-in <a class="header-anchor" href="#portal-and-sign-in" aria-label="Permalink to &quot;Portal and sign-in&quot;">​</a></h1><p>Visitors can create an account on your public site and sign in later. The account is a contact in your contacts list. On the admin side you see who has access, and you can grant, change or remove it.</p><blockquote><p><strong>In simple words:</strong> Visitors register and sign in on the site. You watch and control access from the contact.</p></blockquote><p>Open <code>Website → Customers</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Portal actions need the customer portal, which comes with the <strong>Website</strong> plugin. The public pages are always part of the site.</p><h2 id="what-a-visitor-does" tabindex="-1">What a visitor does <a class="header-anchor" href="#what-a-visitor-does" aria-label="Permalink to &quot;What a visitor does&quot;">​</a></h2><p>All four pages are on the public site. The site header has <strong>Login</strong> and <strong>Register</strong> links.</p><h3 id="register" tabindex="-1">Register <a class="header-anchor" href="#register" aria-label="Permalink to &quot;Register&quot;">​</a></h3><p>Address: <code>/register</code>.</p><ol><li>Click <strong>Register</strong> in the site header.</li><li>Enter <strong>Name</strong>, <strong>Email address</strong>, <strong>Password</strong> and <strong>Confirm password</strong>. All four are required.</li><li>Click <strong>Create account</strong>.</li></ol>',11)),r(a,{src:"/images1/website/portal_register.png",alt:"Public /register page filled for Nina Patel: name, email nina.patel@example.com, password dots"}),t[1]||(t[1]=o('<p>The visitor is now a contact. If a visitor already has an account, the <strong>Log in</strong> link opens the sign-in page.</p><h3 id="login" tabindex="-1">Login <a class="header-anchor" href="#login" aria-label="Permalink to &quot;Login&quot;">​</a></h3><p>Address: <code>/login</code>.</p><ol><li>Click <strong>Login</strong> in the site header.</li><li>Enter <strong>Email address</strong> and <strong>Password</strong>. Both are required.</li><li>Tick <strong>Remember me</strong> to stay signed in.</li><li>Click <strong>Sign in</strong>.</li></ol>',4)),r(a,{src:"/images1/website/portal_login.png",alt:"Public /login page with Email address, Password, Forgot password?, Remember me, Sign in and the Create account link"}),t[2]||(t[2]=o('<p>If the details are wrong, the page says &quot;These credentials do not match our records.&quot; After too many attempts, it asks the visitor to wait.</p><h3 id="forgot-password" tabindex="-1">Forgot password <a class="header-anchor" href="#forgot-password" aria-label="Permalink to &quot;Forgot password&quot;">​</a></h3><ol><li>On the login page, click <strong>Forgot password?</strong>.</li><li>Enter <strong>Email address</strong>.</li><li>Click <strong>Send reset link</strong>.</li></ol>',3)),r(a,{src:"/images1/website/portal_forgot.png",alt:"Forgot password page with the email field filled and the Send reset link button"}),t[3]||(t[3]=o('<p><strong>Back to login</strong> returns to the sign-in page.</p><h3 id="reset-password" tabindex="-1">Reset password <a class="header-anchor" href="#reset-password" aria-label="Permalink to &quot;Reset password&quot;">​</a></h3><p>The link in the reset email opens the <strong>Reset password</strong> page.</p><ol><li>Check <strong>Email address</strong>.</li><li>Enter <strong>New password</strong> and <strong>Confirm new password</strong>.</li><li>Click <strong>Reset password</strong>.</li></ol><p>The page shows the <strong>Email address</strong> and the two password fields.</p><p>The link from <strong>Grant Portal Access</strong> works the same way, so a new customer uses it to choose a first password.</p><h2 id="grant-access-to-a-contact" tabindex="-1">Grant access to a contact <a class="header-anchor" href="#grant-access-to-a-contact" aria-label="Permalink to &quot;Grant access to a contact&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Outgoing email must be set up first. Without it the contact never gets the link.</p></div><ol><li>Open <code>Website → Customers</code> and open the contact.</li><li>Open the <strong>Portal Access</strong> menu in the header.</li><li>Click <strong>Grant Portal Access</strong>.</li><li>The page shows <strong>Portal Access: Granted</strong>. The contact receives an email with a link to choose a password.</li></ol><h2 id="what-you-see-as-admin" tabindex="-1">What you see as admin <a class="header-anchor" href="#what-you-see-as-admin" aria-label="Permalink to &quot;What you see as admin&quot;">​</a></h2><h3 id="portal-access-badge-and-filter" tabindex="-1">Portal Access badge and filter <a class="header-anchor" href="#portal-access-badge-and-filter" aria-label="Permalink to &quot;Portal Access badge and filter&quot;">​</a></h3><p>On <code>Website → Customers</code>, a <strong>Portal Access</strong> badge marks contacts that can sign in. Use the <strong>Portal Access</strong> filter to list only those contacts.</p><h3 id="customer-portal-section" tabindex="-1">Customer Portal section <a class="header-anchor" href="#customer-portal-section" aria-label="Permalink to &quot;Customer Portal section&quot;">​</a></h3><p>Open a customer. The <strong>Customer Portal</strong> section shows:</p><ul><li><strong><em>Portal Access:</em></strong> <strong>Granted</strong> or <strong>Not Granted</strong>.</li><li><strong><em>Email Verified At:</em></strong> When the contact set a password, or <strong>Never</strong>.</li><li><strong><em>Last Portal Login:</em></strong> The last sign-in, or <strong>Never</strong>.</li></ul>',15)),r(a,{src:"/images1/website/portal_status.png",alt:"Contact view page of Nina Patel showing the Customer Portal section with Portal Access: Granted"}),t[4]||(t[4]=e("p",null,[s("A visitor who registered on the site shows as "),e("strong",null,"Granted"),s(". A contact you created in the admin panel shows "),e("strong",null,"Not Granted"),s(" until you grant access.")],-1)),t[5]||(t[5]=e("h2",{id:"manage-access",tabindex:"-1"},[s("Manage access "),e("a",{class:"header-anchor",href:"#manage-access","aria-label":'Permalink to "Manage access"'},"​")],-1)),t[6]||(t[6]=e("p",null,[s("Use the "),e("strong",null,"Portal Access"),s(" menu at the top of the contact view or edit page.")],-1)),r(a,{src:"/images1/website/portal_menu.png",alt:"Contact page with the Portal Access menu open showing Change Password, Send Password Reset and Revoke Portal Access"}),t[7]||(t[7]=o('<table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Grant Portal Access</strong></td><td>Shows only when the contact has no access. It sends an email so the contact can set a password.</td></tr><tr><td><strong>Change Password</strong></td><td>Shows once access is granted. You set a new password for the contact.</td></tr><tr><td><strong>Send Password Reset</strong></td><td>Emails a reset link to the contact.</td></tr><tr><td><strong>Revoke Portal Access</strong></td><td>Stops the contact from signing in.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The contact needs an email address, and each address can have portal access only once.</p></div><p>For the steps and messages, see <a href="./../../general-settings/users/portal-access.html">Portal access</a>. Vendors use the same portal. See <a href="./../../supply-chain/purchase/orders/vendor-portal.html">Vendor portal</a>.</p><h2 id="what-the-visitor-sees" tabindex="-1">What the visitor sees <a class="header-anchor" href="#what-the-visitor-sees" aria-label="Permalink to &quot;What the visitor sees&quot;">​</a></h2><p>After signing in, the visitor browses the same public site. Pages stay at <code>/</code>, <code>/pages/{slug}</code> and <code>/blog</code>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./customers.html">Website customers</a></li><li><a href="./">Customers overview</a></li><li><a href="./../../general-settings/users/portal-access.html">Portal access</a></li><li><a href="./../../getting-started/contacts/contacts.html">Contacts</a></li></ul>',7))])}const _=n(d,[["render",g]]);export{P as __pageData,_ as default};
